def pancake_sort(nums):
    if not nums:
        return nums

    sorted_nums = nums.copy()

    for i in range(len(nums) - 1, 0, -1):
        max_idx = 0
        for j in range(1, i + 1):
            if sorted_nums[j] > sorted_nums[max_idx]:
                max_idx = j

        if max_idx != i:
            # Flip the array from index 0 to max_idx
            sorted_nums[:max_idx + 1] = sorted_nums[:max_idx + 1][::-1]

            # Flip the array from index 0 to i
            sorted_nums[:i + 1] = sorted_nums[:i + 1][::-1]

    return sorted_nums
