def eulerian_num(n, m):
    # Eulerian numbers can be computed using the following recurrence relation:
    # A(n, m) = (m+1)*A(n-1, m) + (n-m)*A(n-1, m-1) with base cases:
    # A(n, n-1) = 1 for any n >= 1
    # A(1, 0) = 1

    # Using dynamic programming to fill a table of Eulerian numbers up to n
    # Initialize a table (2D array) with zeros
    table = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # Base cases
    for i in range(1, n + 1):
        table[i][i - 1] = 1  # A(n, n-1) = 1

    for i in range(2, n + 1):
        for j in range(0, i):
            if j == i - 1:
                table[i][j] = 1
            else:
                table[i][j] = (j + 1) * table[i - 1][j] + (i - j) * table[i - 1][j - 1]

    return table[n][m]
